 note='Final Pass 03/07 remediation: expanded C2 Unit 03 into the 700–1200-word production band with explicit underdetermination, calibration, extrapolation, idealization, and verification reasoning while preserving lexical exposure contracts.';notes=r.setdefault('quality',{}).setdefault('notes',[])
 if note not in notes:notes.append(note)
